147	/// The wizard's questions; a scripted implementation drives tests. `None` means the contributor cancelled.
148	trait AddPrompter {
149	    /// The indices the contributor ticked; `checked` says which start ticked. `None` on Esc.
150	    fn multi_select(
151	        &mut self,
152	        prompt: &str,
153	        items: &[String],
154	        checked: &[bool],
155	    ) -> Result<Option<Vec<usize>>, CliError>;
156	    /// The summary; an empty answer opens `$EDITOR` for a longer one. `None` when the editor saves nothing.
157	    fn summary(&mut self, prompt: &str) -> Result<Option<Summary>, CliError>;
158	    /// `None` on Esc.
159	    fn confirm(&mut self, prompt: &str, default: bool) -> Result<Option<bool>, CliError>;
160	}
