216	/// A package the wizard offers, and whether it changed since its last tag.
217	struct Choice {
218	    name: String,
219	    changed: bool,
220	}
221	
222	/// The interactive wizard (as in `@changesets/cli`): packages, which are major, which of the rest are minor (the
223	/// remainder default to patch), a summary unless one was given, then a review to confirm. Changed packages are listed
224	/// first and start ticked. `None` when the contributor cancels, having been told nothing was written.
225	fn run_wizard(
226	    choices: &[Choice],
227	    summary: Option<Summary>,
228	    prompter: &mut impl AddPrompter,
229	) -> Result<Option<(Vec<Entry>, Summary)>, CliError> {
230	    let answers = ask(choices, summary, prompter)?;
231	    if answers.is_none() {
232	        prompt_line(tty::CANCELLED);
233	    }
234	    Ok(answers)
235	}
236	
237	fn ask(
238	    choices: &[Choice],
239	    summary: Option<Summary>,
240	    prompter: &mut impl AddPrompter,
241	) -> Result<Option<(Vec<Entry>, Summary)>, CliError> {
242	    if choices.is_empty() {
243	        return Err(CliError::AddNoPackagesInWorkspace);
244	    }
245	
246	    let mut ordered: Vec<&Choice> = choices.iter().collect();
247	    ordered.sort_by_key(|choice| !choice.changed);
248	    let labels: Vec<String> = ordered
249	        .iter()
250	        .map(|choice| {
251	            if choice.changed {
252	                format!("{} (changed)", choice.name)
253	            } else {
254	                choice.name.clone()
255	            }
256	        })
257	        .collect();
258	    let checked: Vec<bool> = ordered.iter().map(|choice| choice.changed).collect();
259	    let Some(selected_indices) = prompter.multi_select(
260	        "Packages in this change (Space toggles, Enter confirms, Esc cancels)",
261	        &labels,
262	        &checked,
263	    )?
264	    else {
265	        return Ok(None);
266	    };
267	    if selected_indices.is_empty() {
268	        return Err(CliError::AddNoPackagesSelected);
269	    }
270	    let selected_packages: Vec<String> = selected_indices.into_iter().map(|i| ordered[i].name.clone()).collect();
271	    let unticked = vec![false; selected_packages.len()];
272	
273	    let Some(majors) = prompter.multi_select(
274	        "Which are a MAJOR bump? (breaking changes only)",
275	        &selected_packages,
276	        &unticked,
277	    )?
278	    else {
279	        return Ok(None);
280	    };
281	    let major_set: std::collections::HashSet<usize> = majors.into_iter().collect();
282	
283	    let minor_candidates: Vec<String> = selected_packages
284	        .iter()
285	        .enumerate()
286	        .filter(|(idx, _)| !major_set.contains(idx))
287	        .map(|(_, name)| name.clone())
288	        .collect();
289	    let minor_set: std::collections::HashSet<String> = if minor_candidates.is_empty() {
290	        std::collections::HashSet::new()
291	    } else {
292	        let Some(minors) = prompter.multi_select(
293	            "Which are a MINOR bump? (the rest get PATCH)",
294	            &minor_candidates,
295	            &unticked[..minor_candidates.len()],
296	        )?
297	        else {
298	            return Ok(None);
299	        };
300	        minors.into_iter().map(|idx| minor_candidates[idx].clone()).collect()
301	    };
302	
303	    let entries: Vec<Entry> = selected_packages
304	        .iter()
305	        .enumerate()
306	        .map(|(idx, name)| Entry {
307	            name: name.clone(),
308	            severity: if major_set.contains(&idx) {
309	                Severity::Major
310	            } else if minor_set.contains(name) {
311	                Severity::Minor
312	            } else {
313	                Severity::Patch
314	            },
315	        })
316	        .collect();
317	
318	    let summary = match summary {
319	        Some(summary) => summary,
320	        None => match prompter.summary("Changelog summary")? {
321	            Some(summary) => summary,
322	            None => return Ok(None),
323	        },
324	    };
325	
326	    prompt_line(&review(&entries, &summary.0));
327	    match prompter.confirm("Write this changeset?", true)? {
328	        Some(true) => Ok(Some((entries, summary))),
329	        Some(false) | None => Ok(None),
330	    }
331	}
332	
333	/// What the changeset will record: each package's bump, then the summary as it reaches the changelog.
334	fn review(entries: &[Entry], summary: &str) -> String {
335	    let mut text = String::from("\nThis changeset records:\n");
336	    for entry in entries {
337	        text.push_str(&format!("  {:<5}  {}\n", entry.severity.to_string(), entry.name));
338	    }
339	    text.push('\n');
340	    for line in summary.trim().lines() {
341	        text.push_str(&format!("  {line}\n"));
342	    }
343	    text
344	}
