346	/// Parses a CLI-supplied severity string, reporting every value `Severity`
347	/// actually accepts (`none`, `patch`, `minor`, `major`) on failure -- not a
348	/// stale subset that omits `none`.
349	fn parse_severity(sev_str: &str) -> Result<Severity, CliError> {
350	    sev_str.parse().map_err(|_err| CliError::InvalidSeverity {
351	        value: sev_str.to_string(),
352	    })
353	}
