355	/// The wizard's packages, named by `.display_name()` so `cargo/foo` and `npm/foo` stay distinct in a polyglot workspace.
356	fn wizard_choices<'a>(
357	    packages: impl Iterator<Item = &'a callisto_model::Package>,
358	    changed: &std::collections::BTreeMap<callisto_model::PackageId, bool>,
359	) -> Vec<Choice> {
360	    packages
361	        .map(|pkg| Choice {
362	            name: pkg.id.display_name(),
363	            changed: changed.get(&pkg.id).copied().unwrap_or(false),
364	        })
365	        .collect()
366	}
